import{_ as t,o as e,c as s,a4 as i}from"./chunks/framework.BUqnS5H7.js";const h=JSON.parse('{"title":"为什么 Kafka 这么快","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/04-performance/chapter-01-why-kafka-is-fast.md","filePath":"kafka/04-performance/chapter-01-why-kafka-is-fast.md"}'),r={name:"kafka/04-performance/chapter-01-why-kafka-is-fast.md"};function l(n,a,f,d,k,p){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="为什么-kafka-这么快" tabindex="-1" data-src-line="1" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">为什么 Kafka 这么快 <a class="header-anchor" href="#为什么-kafka-这么快" aria-label="Permalink to &quot;为什么 Kafka 这么快&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><p data-src-line="3" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">Kafka 的高吞吐不是魔法，而是四个机制的叠加：顺序写入、零拷贝、批处理、页缓存。本文逐个拆解。</p></blockquote><h2 id="_1-顺序写入" tabindex="-1" data-src-line="5" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">1. 顺序写入 <a class="header-anchor" href="#_1-顺序写入" aria-label="Permalink to &quot;1. 顺序写入&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">消息追加到日志文件末尾，永远不修改已有数据。这是 Kafka 高吞吐的根基。</p><table tabindex="0"><thead data-src-line="9" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="9" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><th style="text-align:left;">写入方式</th><th style="text-align:left;">吞吐量</th><th style="text-align:left;">原因</th></tr></thead><tbody data-src-line="11" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="11" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">顺序写</td><td style="text-align:left;">~600 MB/s（机械硬盘）</td><td style="text-align:left;">磁盘顺序读写接近内存速度</td></tr><tr data-src-line="12" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">随机写</td><td style="text-align:left;">~2 MB/s（机械硬盘）</td><td style="text-align:left;">磁盘寻道时间 ~10ms，每次写入都要移动磁头</td></tr></tbody></table><p data-src-line="14" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">Kafka 把随机写变成了顺序写——消息只能追加到 Partition 的活跃 Segment 末尾，永远不修改、不删除已有数据（删除是整个 Segment 级别的）。</p><h2 id="_2-零拷贝" tabindex="-1" data-src-line="16" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">2. 零拷贝 <a class="header-anchor" href="#_2-零拷贝" aria-label="Permalink to &quot;2. 零拷贝&quot;">​</a></h2><p data-src-line="18" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">传统方式读取文件发送到网络：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 → 内核缓冲区 → 用户空间 → Socket 缓冲区 → 网卡</span></span>
<span class="line"><span>        4 次拷贝，4 次上下文切换</span></span></code></pre></div><p data-src-line="25" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">Kafka 使用 <code>sendfile()</code> 系统调用：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 → 内核缓冲区 → 网卡</span></span>
<span class="line"><span>        2 次拷贝，2 次上下文切换</span></span></code></pre></div><p data-src-line="32" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">数据从不经过用户空间，CPU 开销大幅降低。这在消费者读取消息时生效——Broker 直接把日志文件的内容通过零拷贝发送给消费者。</p><h2 id="_3-批处理" tabindex="-1" data-src-line="34" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">3. 批处理 <a class="header-anchor" href="#_3-批处理" aria-label="Permalink to &quot;3. 批处理&quot;">​</a></h2><p data-src-line="36" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">生产者把多条消息打包成一个请求发送，而不是逐条发送：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">props.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;batch.size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65536</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 64KB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">props.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;linger.ms&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 最多等 20ms</span></span></code></pre></div><table tabindex="0"><thead data-src-line="43" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="43" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><th style="text-align:left;">效果</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="45" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="45" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">减少网络往返</td><td style="text-align:left;">1 个请求包含 100 条消息，比 100 个请求少 99 次 TCP 往返</td></tr><tr data-src-line="46" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">提高压缩比</td><td style="text-align:left;">批次越大，压缩算法越能利用消息间的相似性</td></tr><tr data-src-line="47" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">减少 Broker 端 I/O</td><td style="text-align:left;">Broker 一次写入更大的连续块</td></tr></tbody></table><h2 id="_4-页缓存" tabindex="-1" data-src-line="49" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">4. 页缓存 <a class="header-anchor" href="#_4-页缓存" aria-label="Permalink to &quot;4. 页缓存&quot;">​</a></h2><p data-src-line="51" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">Kafka 的消息写入操作不直接落到磁盘，而是写入操作系统的<strong>页缓存</strong>（Page Cache）：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer → 页缓存 → 异步刷盘</span></span>
<span class="line"><span>Consumer ← 页缓存（如果消息还没落盘，直接从内存读）</span></span></code></pre></div><table tabindex="0"><thead data-src-line="58" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="58" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><th style="text-align:left;">优势</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="60" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><tr data-src-line="60" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">写入延迟低</td><td style="text-align:left;">写入页缓存是内存操作，延迟微秒级</td></tr><tr data-src-line="61" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">读取命中率高</td><td style="text-align:left;">消费者通常读最近写入的消息，这些消息大概率还在页缓存中</td></tr><tr data-src-line="62" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><td style="text-align:left;">不占 JVM 堆</td><td style="text-align:left;">页缓存由操作系统管理，不经过 JVM 垃圾回收</td></tr></tbody></table><p data-src-line="64" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">Kafka 没有把数据加载到 JVM 堆再返回，而是让操作系统直接管理缓存——这是它比很多消息队列快的关键原因之一。</p><h2 id="_5-四个机制的协同" tabindex="-1" data-src-line="66" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">5. 四个机制的协同 <a class="header-anchor" href="#_5-四个机制的协同" aria-label="Permalink to &quot;5. 四个机制的协同&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入路径：</span></span>
<span class="line"><span>  Producer → 批处理 → 顺序写入页缓存 → 异步刷盘</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>          压缩（批越大压缩比越高）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>读取路径：</span></span>
<span class="line"><span>  Consumer ← 零拷贝 ← 页缓存（或磁盘顺序读）</span></span></code></pre></div><p data-src-line="78" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">每个机制都不是 Kafka 发明的，但它们的组合是 Kafka 的核心竞争力。</p><h2 id="_6-延伸阅读" tabindex="-1" data-src-line="80" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">6. 延伸阅读 <a class="header-anchor" href="#_6-延伸阅读" aria-label="Permalink to &quot;6. 延伸阅读&quot;">​</a></h2><ul data-src-line="82" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md"><li data-src-line="82" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">生产者端的批量和压缩参数调优：<a href="./chapter-02-throughput-tuning.html">吞吐调优</a></li><li data-src-line="83" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">压缩算法的选择：<a href="./chapter-04-compression-tradeoff.html">压缩权衡</a></li><li data-src-line="84" data-src-file="kafka/04-performance/chapter-01-why-kafka-is-fast.md">日志分段与索引的字节级细节：<a href="./../reference/chapter-02-log-segment.html">日志分段与索引</a></li></ul>`,26)])])}const o=t(r,[["render",l]]);export{h as __pageData,o as default};
